package com.learnspherex.auth;
import jakarta.validation.constraints.*; import java.util.*;
public final class AuthDtos { private AuthDtos(){} public record RegisterRequest(@NotBlank @Size(max=50) String username,@NotBlank @Email String email,@NotBlank @Size(min=8,max=100) String password,@NotBlank String firstName,@NotBlank String lastName,@Size(max=20) String phone,@NotNull RoleName role){} public record LoginRequest(@NotBlank String username,@NotBlank String password){} public record ChangePasswordRequest(@NotBlank String currentPassword,@NotBlank @Size(min=8,max=100) String newPassword){} public record AccountStatusRequest(@NotNull Boolean active){} public record ProfileUpdateRequest(@NotBlank String firstName,@NotBlank String lastName,@Size(max=20) String phone){} public record AuthResponse(String token,String tokenType,Long userId,String username,Set<RoleName> roles){} public record UserResponse(Long id,String username,String email,String firstName,String lastName,String phone,AccountStatus status,Set<RoleName> roles){} }
